def bracket_depth(s: str) -> int:
    """
    Returns the maximal nesting depth of correctly matched brackets in the string.
    If the brackets are not properly matched, returns -1.
    Non-bracket characters are ignored.
    """
    stack = []
    max_depth = 0
    opening = {'(', '[', '{'}
    closing_map = {')': '(', ']': '[', '}': '{'}

    for ch in s:
        if ch in opening:
            stack.append(ch)
            if len(stack) > max_depth:
                max_depth = len(stack)
        elif ch in closing_map:
            if not stack:
                return -1
            if stack[-1] != closing_map[ch]:
                return -1
            stack.pop()
    if stack:
