    stack = []
    max_depth = 0

    for ch in s:
        if ch in opening:
            stack.append(ch)
            max_depth = max(max_depth, len(stack))
        elif ch in closing:
            if not stack or stack[-1] != pairs[ch]:
                return -1
            stack.pop()
    if stack:
        return -1
    return max_depth
